// FLUXO 1 — palavras-chave DETERMINISTICAS (vocabulario controlado).
// Espelha src/servicos/matchIA.js::gerarPalavrasChave do backend. NAO deixar a
// LLM inventar tags: o ranking (recomendacaoService) casa por estes tokens.
const body = $input.first().json.body || $input.first().json;
const q = body.respostas || {};
const norm = (s) => (s ?? '').toString().toLowerCase().trim();
const inclui = (txt, ...termos) => termos.some((t) => norm(txt).includes(t));
const tags = new Set();
const add = (...t) => t.forEach((x) => x && tags.add(x));

const tempo = norm(q.tempo_sozinho);
if (tempo.includes('menos de 4')) add('muito-presente');
else if (tempo.includes('4 e 8')) add('meio-periodo');
else if (tempo.includes('mais de 8')) add('passa-o-dia-fora');

const energia = norm(q.nivel_energia);
if (energia.includes('alto')) add('energia-alta');
else if (energia.includes('moderado')) add('energia-moderada');
else if (energia.includes('baixo')) add('energia-baixa');

const passeios = norm(q.frequencia_passeios);
if (passeios.includes('intensa')) add('passeios-intensos');
else if (passeios.includes('moderada')) add('passeios-moderados');
else if (passeios.includes('leve')) add('passeios-leves');
else if (passeios.includes('nenhuma')) add('sem-passeios');

const lar = norm(q.tipo_residencia);
if (lar.includes('apartamento')) { add('apartamento'); add(lar.includes('sem tela') ? 'sem-tela' : 'com-tela'); }
else if (lar.includes('quintal grande')) add('quintal-grande');
else if (lar.includes('quintal pequeno')) add('quintal-pequeno');

if (norm(q.existem_criancas) === 'sim') add('tem-criancas');
if (q.outros_animais && !inclui(q.outros_animais, 'não', 'nao', 'informado', 'nenhum')) add('tem-outros-animais');

const especie = norm(q.preferencia_especie);
if (especie.includes('gato')) add('quer-gato');
else if (especie.includes('cã') || especie.includes('cachorro') || especie.includes('cao')) add('quer-cao');

const porte = norm(q.porte_preferido);
if (porte.includes('pequeno')) add('porte-pequeno');
else if (porte.includes('médio') || porte.includes('medio')) add('porte-medio');
else if (porte.includes('grande')) add('porte-grande');

const idade = norm(q.idade_preferida);
if (idade.includes('filhote')) add('quer-filhote');
else if (idade.includes('adulto')) add('quer-adulto');
else if (idade.includes('idoso')) add('quer-idoso');

if (norm(q.alergia_pelos) === 'sim') add('alergia-pelos');
if (norm(q.classificacao_experiencia).includes('experiente')) add('experiente');
else if (norm(q.classificacao_experiencia).includes('nenhuma')) add('iniciante');
if (norm(q.reserva_custos_vet) === 'sim') add('tem-reserva-vet');

return [{ json: { tags: [...tags], body } }];

// Texto legivel do adotante para a LLM. Usa os rotulos amigaveis que o backend
// ja envia em tutor.respostas_rotuladas; cai para as colunas cruas se faltar.
const body = $input.first().json.body;
const tutor = body.tutor || {};
const respostas = tutor.respostas_rotuladas || body.respostas || {};
const tags = $input.first().json.tags || [];
let userText = `Adotante: ${tutor.nome || 'Nao informado'}\n\nRespostas do questionario:\n`;
for (const [pergunta, resposta] of Object.entries(respostas)) {
  if (resposta == null || resposta === '') continue;
  userText += `- ${pergunta}: ${resposta}\n`;
}
userText += `\nPalavras-chave detectadas: ${tags.join(', ') || '—'}`;
return [{ json: { userText } }];

// Junta as tags deterministicas (Fluxo 1) com o relatorio da LLM.
const relatorio = $input.first().json?.choices?.[0]?.message?.content || '';
const tags = $('Palavras-chave').first().json.tags || [];
return [{ json: { palavras_chave: tags, relatorio } }];
